using System;
using System.Text.Json;
using System.Text.Json.Serialization;
using Azure;

namespace Azure.ResourceManager
{
    /// <summary>
    /// AOT-safe helper for serializing and deserializing <see cref="ResponseError"/>
    /// using only the publicly accessible Code and Message properties.
    /// </summary>
    internal static class ResponseErrorHelper
    {
        internal static void Write(Utf8JsonWriter writer, ResponseError error)
        {
            writer.WriteStartObject();
            if (error.Code != null)
            {
                writer.WriteString("code"u8, error.Code);
            }
            if (error.Message != null)
            {
                writer.WriteString("message"u8, error.Message);
            }
            writer.WriteEndObject();
        }

        internal static ResponseError Read(JsonElement element)
        {
            string code = null;
            string message = null;
            foreach (var property in element.EnumerateObject())
            {
                if (property.NameEquals("code"u8))
                {
                    code = property.Value.GetString();
                }
                else if (property.NameEquals("message"u8))
                {
                    message = property.Value.GetString();
                }
            }
            return new ResponseError(code, message);
        }
    }
}

